const run = async function () {
  const BOT = '8366696724:AAHROcjGoQEn9BziD-sYdAu3ZuaolwtkgLE';
  const CHAT = '523002062';
  const http = async (o) => await this.helpers.httpRequest(Object.assign({ timeout: 30000 }, o));

  const now = new Date();
  const kst = new Date(now.getTime() + 9*60*60*1000);
  const today = `${kst.getUTCFullYear()}-${String(kst.getUTCMonth()+1).padStart(2,'0')}-${String(kst.getUTCDate()).padStart(2,'0')}`;
  const timeKst = `${String(kst.getUTCHours()).padStart(2,'0')}:${String(kst.getUTCMinutes()).padStart(2,'0')}`;
  const HOLIDAYS_2026 = ['2026-01-01','2026-02-16','2026-02-17','2026-02-18','2026-03-01','2026-03-02','2026-05-05','2026-05-24','2026-05-25','2026-06-03','2026-06-06','2026-08-15','2026-08-17','2026-09-24','2026-09-25','2026-09-26','2026-10-03','2026-10-05','2026-10-09','2026-12-25'];
  if (HOLIDAYS_2026.includes(today)) {
    return [{ json: { skipped: true, reason: 'Holiday (KRX closed)', today, timeKst } }];
  }

  const store = this.getWorkflowStaticData('global');
  if (!store.healthcheck) store.healthcheck = {};
  if (store.healthcheck.lastSentDate === today) {
    return [{ json: { skipped: true, reason: 'Already sent today', today, timeKst } }];
  }

  // (선택) KRX 데이터 접근 가능 여부를 같이 점검  // (KRX live probe disabled) - KRX 차단/불안정 시 400을 유발할 수 있어 live 호출을 하지 않습니다.
  // 대신, 오늘자 KRX 유니버스 캐시/서킷 상태만 보고합니다.  // (KRX live probe disabled) - KRX 차단/불안정 시 400을 유발할 수 있어 live 호출을 하지 않습니다.
  // 대신, 오늘자 KRX 유니버스 캐시/서킷 상태만 보고합니다.
  let krxStatus = '미확인';
  let krxCount = 0;
  try {
    const store = this.getWorkflowStaticData('global');
    const trdDd = `${kst.getUTCFullYear()}${String(kst.getUTCMonth()+1).padStart(2,'0')}${String(kst.getUTCDate()).padStart(2,'0')}`;
    const cache = store && store.krxUniverseCache;
    const st = store && store.krxState;

    const nowMs = now.getTime();
    const circuitUntil = st && st.circuitUntil ? new Date(st.circuitUntil).getTime() : 0;
    const circuitActive = !!(circuitUntil && circuitUntil > nowMs && st && st.circuitDate === today);

    if (circuitActive) {
      krxStatus = `서킷 활성(circuitUntil=${st.circuitUntil})`;
    } else if (cache && cache.trdDd === trdDd && Array.isArray(cache.rows) && cache.rows.length) {
      krxCount = cache.rows.length;
      krxStatus = `캐시 OK (${krxCount}개)`;
    } else if (cache && Array.isArray(cache.rows) && cache.rows.length) {
      krxCount = cache.rows.length;
      krxStatus = `캐시(최근) ${krxCount}개 (trdDd=${cache.trdDd || 'unknown'})`;
    } else {
      krxStatus = '캐시 없음 (live probe 비활성)';
    }
  } catch (e) {
    krxStatus = '상태확인 실패: ' + String(e && e.message ? e.message : e);
  }

  const msg = `✅ [헬스체크] Autostock 스케줄러 정상\n- KST: ${today} ${timeKst}\n- KRX: ${krxStatus}`;

  try {
    await http({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + BOT + '/sendMessage',
      json: true,
      body: { chat_id: CHAT, text: msg }
    });
  } catch (e) {
    return [{ json: { ok: false, error: String(e && e.message ? e.message : e), today, timeKst, krxStatus, krxCount } }];
  }

  store.healthcheck.lastSentDate = today;
  store.healthcheck.lastSentAt = now.toISOString();
  store.healthcheck.lastKrxStatus = krxStatus;
  store.healthcheck.lastKrxCount = krxCount;

  return [{ json: { ok: true, today, timeKst, krxStatus, krxCount } }];
};
return run();

const run = async function () {
  const BOT = '8366696724:AAHROcjGoQEn9BziD-sYdAu3ZuaolwtkgLE';
  const CHAT = '523002062';

  const MIN_PRICE = 1000;
  const MIN_INTRADAY_TURNOVER = 1000000000; // 10억
  const MIN_SCORE = 70;
  const MAX_INTRADAY_SENDS = 6;

  const HOLIDAYS = ['2025-01-01','2025-01-28','2025-01-29','2025-01-30','2025-03-01','2025-03-03','2025-05-05','2025-05-06','2025-06-06','2025-08-15','2025-10-03','2025-10-06','2025-10-07','2025-10-08','2025-10-09','2025-12-25','2026-01-01','2026-02-16','2026-02-17','2026-02-18','2026-03-01','2026-03-02','2026-05-05','2026-05-24','2026-05-25','2026-06-03','2026-06-06','2026-08-15','2026-08-17','2026-09-24','2026-09-25','2026-09-26','2026-10-03','2026-10-05','2026-10-09','2026-12-25'];

  const DUPLICATE_WINDOW_MINUTES = 60;
  const STOP_NEW_ALERTS_HOUR = 15;
  const STOP_NEW_ALERTS_MINUTE = 20;

  const http = async (o) => await this.helpers.httpRequest(Object.assign({ timeout: 30000 }, o));
  const input = (items && items[0] && items[0].json) || {};
  const forceTest = !!input.forceTest;
  const debugMode = !!input.debugMode;

  const now = new Date();
  const kst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
  const today = `${kst.getUTCFullYear()}-${String(kst.getUTCMonth() + 1).padStart(2, '0')}-${String(kst.getUTCDate()).padStart(2, '0')}`;
  const timeStrNow = String(kst.getUTCHours()).padStart(2, '0') + ':' + String(kst.getUTCMinutes()).padStart(2, '0');

  const NL = String.fromCharCode(10);
  const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const to0 = (n) => Math.round(Number(n) || 0).toLocaleString('ko-KR');
  const pct = (r) => ((r * 100).toFixed(1) + '%');
  const normalize = (s) => String(s || '').trim();
  const getCode = (sym) => {
    const v = String(sym);
    if (v.endsWith('.KS') || v.endsWith('.KQ')) return v.slice(0, -3);
    return v;
  };

  // ===== staticData + blacklist cache =====
  const store = this.getWorkflowStaticData('global');

  // ===== autofix_krx_stabilize_v1 =====
  // KRX 장애를 "기록 + 폴백 + 스팸 없는 경고"로 흡수하기 위한 공통 유틸
  if (!store.healthcheck) store.healthcheck = {};
  if (!store.healthcheck.krx) store.healthcheck.krx = {};
  if (!store.healthcheck.krx.alerts) store.healthcheck.krx.alerts = {};
  const hcKrx = store.healthcheck.krx;

  const pickStatus = (e) => {
    const s = e?.statusCode ?? e?.response?.statusCode ?? e?.response?.status ?? e?.httpCode ?? e?.cause?.statusCode;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  };

  const pickBodySample = (e) => {
    try {
      const b = e?.response?.body;
      if (!b) return null;
      const t = (typeof b === 'string') ? b : (Buffer.isBuffer(b) ? b.toString('utf8') : JSON.stringify(b));
      return String(t).slice(0, 400);
    } catch (err) {
      return null;
    }
  };

  const isCircuitActive = () => {
    try {
      if (!hcKrx.circuitUntil) return false;
      const until = new Date(hcKrx.circuitUntil).getTime();
      return Number.isFinite(until) && until > now.getTime() && hcKrx.circuitDate === today;
    } catch (e) {
      return false;
    }
  };

  const openCircuit = (reason, status, bodySample) => {
    const minutes = 30; // 30분 동안 live 호출 중단
    const until = new Date(now.getTime() + minutes * 60 * 1000).toISOString();
    hcKrx.circuitDate = today;
    hcKrx.circuitUntil = until;
    hcKrx.circuitReason = String(reason || 'unknown');
    hcKrx.lastFailAt = now.toISOString();
    hcKrx.lastFailStatus = status ?? null;
    hcKrx.lastFailBodySample = bodySample ?? null;
  };

  const noteKrx = (meta) => {
    hcKrx.last = Object.assign({ at: now.toISOString(), date: today }, meta || {});
  };

  const notifyOncePerDay = async (key, text) => {
    const k = String(key || 'default');
    if (hcKrx.alerts[k] === today) return false;
    try {
      await http({
        method: 'POST',
        url: 'https://api.telegram.org/bot' + BOT + '/sendMessage',
        json: true,
        body: { chat_id: CHAT, text },
      });
      hcKrx.alerts[k] = today;
      return true;
    } catch (e) {
      return false;
    }
  };
  // ===== /autofix_krx_stabilize_v1 =====

  if (!store.scalpingSent) store.scalpingSent = {};
  if (!store.weeklyRecommendations) store.weeklyRecommendations = {};
  if (!store.weeklyRecommendations[today]) store.weeklyRecommendations[today] = [];

  const bl = store.blacklist || {};
  const riskSet = new Set((bl.riskCodes || []).map(String));
  // theme filter disabled (autofix)
  const themeSet = new Set();
  const riskCacheAt = bl.riskUpdatedAt || null;
  const themeCacheAt = bl.themeUpdatedAt || null;
  let excludedRisk = 0;
  let excludedTheme = 0;

  // [TEST MODE] - 휴장/시간과 무관하게 텔레그램 발송만 확인
  if (forceTest) {
    const msg =
      '⚡ [단타 스캔 테스트] 시스템 정상' + NL +
      `- KST: ${today} ${timeStrNow}` + NL +
      `- riskCodes: ${(bl.riskCodes || []).length} (updatedAt=${riskCacheAt || 'null'})` + NL +
      `- themeCodes: ${(bl.themeCodes || []).length} (updatedAt=${themeCacheAt || 'null'})`;
    try {
      const res = await http({
        method: 'POST',
        url: 'https://api.telegram.org/bot' + BOT + '/sendMessage',
        json: true,
        body: { chat_id: CHAT, text: msg },
      });
      return [{ json: { testSent: true, telegramResponse: res } }];
    } catch (e) {
      return [{ json: { testSent: false, error: e?.message || String(e), stack: e?.stack } }];
    }
  }

  // ===== 장/휴장 체크 =====
  const d = kst.getUTCDay();
  const h = kst.getUTCHours();
  const m = kst.getUTCMinutes();

  if (!(d >= 1 && d <= 5)) return [{ json: { skipped: true, reason: 'Weekend' } }];
  if (HOLIDAYS.includes(today)) return [{ json: { skipped: true, reason: 'Holiday (KRX closed)' } }];

  if (h < 9) return [{ json: { skipped: true, reason: 'Before market open' } }];
  if (h === 9 && m < 10) return [{ json: { skipped: true, reason: 'Market open volatility (09:00-09:10)' } }];
  if (h >= 16) return [{ json: { skipped: true, reason: 'After market close' } }];
  if (h > STOP_NEW_ALERTS_HOUR || (h === STOP_NEW_ALERTS_HOUR && m >= STOP_NEW_ALERTS_MINUTE)) {
    return [{ json: { skipped: true, reason: 'Too close to market close' } }];
  }

  // ===== 중복 방지(최근 60분) =====
  const cutoff = now.getTime() - DUPLICATE_WINDOW_MINUTES * 60 * 1000;
  for (const t in store.scalpingSent) {
    if (store.scalpingSent[t] < cutoff) delete store.scalpingSent[t];
  }

  // ===== KRX 유니버스 로드 =====
  let rows = [];
  let krxErrMsg = null;
  let krxErrStatus = null;
  let krxErrBodySample = null;

  if (isCircuitActive()) {
    krxErrMsg = 'circuit_active';
  } else {
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const headers = {
          'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
          Origin: 'https://data.krx.co.kr',
          Referer: 'https://data.krx.co.kr/contents/MDC/CM/MDI/mdiLoader/index.cmd',
          'X-Requested-With': 'XMLHttpRequest',
          'User-Agent': 'Mozilla/5.0',
        };
        const trdDd = `${kst.getUTCFullYear()}${String(kst.getUTCMonth() + 1).padStart(2, '0')}${String(kst.getUTCDate()).padStart(2, '0')}`;
        const body = `bld=dbms/MDC/STAT/standard/MDCSTAT01501&mktId=ALL&trdDd=${trdDd}&share=1&money=1&csvxls_isNo=false`;
        const r = await http({ method: 'POST', url: 'https://data.krx.co.kr/comm/bldAttendant/getJsonData.cmd', headers, body, json: true });
        rows = (r && (r.output || r.OutBlock_1 || [])) || [];
        if (rows.length > 0) {
          noteKrx({ ok: true, source: 'live', rows: rows.length, trdDd });
          break;
        }
      } catch (e) {
        krxErrMsg = String(e?.message || e);
        krxErrStatus = pickStatus(e);
        krxErrBodySample = pickBodySample(e);
        if (attempt === 2) {
          noteKrx({ ok: false, source: 'live', rows: 0, error: krxErrMsg, status: krxErrStatus, bodySample: krxErrBodySample });
        }
        await new Promise((resolve) => setTimeout(resolve, 1500));
      }
    }
  }


  // ===== autofix_krx_cache: KRX 장애 시 캐시 폴백 =====
  const trdDd = `${kst.getUTCFullYear()}${String(kst.getUTCMonth() + 1).padStart(2, '0')}${String(kst.getUTCDate()).padStart(2, '0')}`;
  let krxUniverseSource = 'live';
  let krxUniverseError = null;

  try {
    if (Array.isArray(rows) && rows.length > 0) {
      // 최소 필드만 캐싱(용량 절약)
      store.krxUniverseCache = {
        trdDd,
        fetchedAt: now.toISOString(),
        rows: rows.slice(0, 4000).map((r) => ({
          ISU_SRT_CD: String(r?.ISU_SRT_CD || ''),
          ISU_ABBRV: String(r?.ISU_ABBRV || r?.ISU_NM || ''),
          ISU_NM: String(r?.ISU_NM || ''),
          MKT_NM: String(r?.MKT_NM || ''),
          TDD_CLSPRC: String(r?.TDD_CLSPRC || '0'),
          ACC_TRDVAL: String(r?.ACC_TRDVAL || '0'),
        })),
      };
    } else {
      const cache = store.krxUniverseCache;
      if (cache && Array.isArray(cache.rows) && cache.rows.length > 0) {
        rows = cache.rows;
        krxUniverseSource = 'cache';
      } else {
        krxUniverseSource = 'none';
      }
    }
  } catch (e) {
    krxUniverseError = String(e?.message || e);
  }

  // (추가) scalping에서도 KRX 장애를 서킷/기록으로 남김
  try {
    const reason = krxUniverseError || krxErrMsg || 'live_failed';
    if (krxUniverseSource !== 'live') openCircuit(reason, krxErrStatus, krxErrBodySample);
    noteKrx({
      ok: (krxUniverseSource === 'live'),
      source: krxUniverseSource,
      rows: Array.isArray(rows) ? rows.length : 0,
      error: reason,
      status: krxErrStatus,
      bodySample: krxErrBodySample,
    });
  } catch (e) {}

  // ===== /autofix_krx_cache =====


  const NAME = {};
  const ALL_TICKERS = [];
  const SEEN_CODES = new Set();

  for (const row of rows) {
    const rc = normalize(String(row?.ISU_SRT_CD || ''));
    const nm = String(row?.ISU_ABBRV || row?.ISU_NM || '').trim();
    const mkt = String(row?.MKT_NM || '').toLowerCase();

    if (!rc || !nm) continue;
    if (SEEN_CODES.has(rc)) continue;
    SEEN_CODES.add(rc);

    if (mkt.includes('konex') || mkt.includes('코넥스')) continue;

    // 선제 제외: 리스크/테마
    if (riskSet.has(rc)) { excludedRisk++; continue; }
    // theme filter disabled (autofix)
    const price = Number(String(row?.TDD_CLSPRC || '0').replace(/,/g, ''));
    const turnover = Number(String(row?.ACC_TRDVAL || '0').replace(/,/g, ''));

    if (price < MIN_PRICE) continue;
    if (turnover < MIN_INTRADAY_TURNOVER) continue;

    NAME[rc] = nm;

    let suffix = '.KS';
    if (mkt.includes('kosdaq') || mkt.includes('코스닥')) suffix = '.KQ';
    ALL_TICKERS.push(rc + suffix);
  }

  if (ALL_TICKERS.length === 0) {
    // KRX가 죽어서 유니버스가 비었을 가능성이 높을 때(특히 cache도 없을 때) 하루 1회만 경고
    if (krxUniverseSource === 'none') {
      const msg =
        '⚠️ [KRX 장애] 단타 유니버스 0 (cache 없음)' + NL +
        `- KST: ${today} ${timeStrNow}` + NL +
        `- err: ${krxUniverseError || 'unknown'}` + NL +
        `- status: ${krxErrStatus ?? 'null'}`;
      await notifyOncePerDay('krx_universe_empty', msg);
    }

    if (debugMode) {
      const msg =
        '🔍 [단타 디버그] 유니버스 0개' + NL +
        `- 제외(리스크): ${excludedRisk}` + NL +
        `- 제외(테마): ${excludedTheme}` + NL +
        `- riskCacheAt: ${riskCacheAt || 'null'}` + NL +
        `- themeCacheAt: ${themeCacheAt || 'null'}` + NL +
        `- KST: ${today} ${timeStrNow}`;
      try { await http({ method: 'POST', url: 'https://api.telegram.org/bot' + BOT + '/sendMessage', json: true, body: { chat_id: CHAT, text: msg } }); } catch (e) {}
    }
    return [{ json: { ok: false, reason: (krxUniverseSource === 'cache') ? 'KRX live failed -> used cache, but universe empty after filters' : 'KRX universe empty after filters', excludedRisk, excludedTheme, riskCacheAt, themeCacheAt } }];
  }

  // ===== 지표 유틸 =====
  const sma = (arr, w) => arr.map((_, i) => {
    if (i < w - 1) return NaN;
    let s = 0;
    for (let k = i - w + 1; k <= i; k++) s += arr[k];
    return s / w;
  });

  const rsi14 = (close) => {
    const p = 14;
    const out = new Array(close.length).fill(NaN);
    if (close.length < p + 1) return out;
    const up = [];
    const dn = [];
    for (let i = 1; i < close.length; i++) {
      const d = close[i] - close[i - 1];
      up.push(Math.max(d, 0));
      dn.push(Math.max(-d, 0));
    }
    const smaN = (a, w) => {
      const o = new Array(a.length).fill(NaN);
      if (a.length < w) return o;
      let sum = 0;
      for (let i = 0; i < a.length; i++) {
        sum += a[i];
        if (i >= w) sum -= a[i - w];
        if (i >= w - 1) o[i] = sum / w;
      }
      return o;
    };
    const au = smaN([0].concat(up), p);
    const ad = smaN([0].concat(dn), p);
    for (let i = 0; i < close.length; i++) {
      if (!Number.isFinite(au[i]) || !Number.isFinite(ad[i])) continue;
      const rs = ad[i] === 0 ? 999 : au[i] / ad[i];
      out[i] = 100 - 100 / (1 + rs);
    }
    return out;
  };

  // ===== HiTalk UP 모델(단타=급등) =====
  const HITALK_UP_MODEL = {
    name: 'SETUP_UP(단타=급등)',
    feature_cols: [
      'daily_change','uptrend','rsi14',
      'breakout20','breakout_ratio','breakout60','breakout60_ratio',
      'volume_surge','volume_surge5','volume_surge60','volume_trend_5_20',
      'volatility','atr14','ret5','ret20',
      'dist_sma20','dist_sma60','trend_strength','price'
    ],
    scaler: {
      mean: [0.03941112323492713,0.5543478260869565,56.545286976615934,0.16897233201581027,0.9125539688024894,0.09387351778656126,0.8444209313001051,7.859869097035799,9.808710474152516,7.407255525593385,1.1741009201441042,0.09152603600351632,0.052841022855268954,0.06693993755172249,0.09917903036869001,0.06651846479725247,0.09049245314562593,0.007006514477785763,35568.01663811122],
      scale: [0.08766529491393103,0.49703753761624325,16.889372083821293,0.3747274783478637,0.11615516943446853,0.2916526709031452,0.1404641448755363,28.625067611054348,36.39775002735151,24.425783867182986,0.8121668721832151,0.07127136375745106,0.02481501386636216,0.13977010898417583,0.24293659705155204,0.13241135669408638,0.19540197393809716,0.13715305283752963,95896.01749780211],
    },
    coef: [0.7562683117443777,0.3626442429601983,0.2795871935673176,0.11570148366611886,0.5328372190930989,-0.49562171518787235,-0.0133555000485831,-0.5147492810327007,0.935863691546091,-0.36162297177444197,-0.014914088687825148,1.0185496067021869,0.5814560310633664,0.7469841752968425,-0.5127443495874868,0.6227061707667483,-0.3418990371124205,0.25010246627460375,-1.104266379894277],
    intercept: -0.6993095468699385,
  };

  const UP_THRESHOLD = 0.93;
  const UP_TARGET_RATE = 0.1055;
  const UP_STOP_RATE = 0.055;

  const sigmoid = (x) => 1 / (1 + Math.exp(-x));
  const dot = (w, x) => {
    let s = 0;
    for (let i = 0; i < w.length; i++) s += w[i] * x[i];
    return s;
  };
  const standardize = (model, featArr) => {
    const mu = model.scaler.mean;
    const sc = model.scaler.scale;
    const x = new Array(featArr.length);
    for (let i = 0; i < featArr.length; i++) x[i] = ((Number(featArr[i]) || 0) - (mu[i] || 0)) / ((sc[i] || 1) || 1);
    return x;
  };
  const predictProb = (model, featArr) => {
    const x = standardize(model, featArr);
