  // 상관관계 그룹 내 동일 주간 중복 여부 확인
  const isCorrelationDuplicate = (nm, weeklyRecs) => {
    const nmLC = String(nm || '').toLowerCase();
    for (const group of CORRELATION_GROUPS) {
